#pragma once
#include <cstdint>
namespace ks{
class PartModulationTask final{public:enum class Kind{Cutoff,First,Second,Square};enum class Stage{DispatchControl,AwaitControl,CaptureInput,ClearHigh,CompareSentinel,AdmitSentinel,SetSentinel,ScaleCutoff,StoreCutoff,StoreByte,SquareInput,ScaleSquare,ReadGate,AdmitGate,DispatchRefresh,AwaitRefresh,DispatchGlobals,AwaitGlobals,Finish,Complete};enum class Read{Input,Gate};enum class Child{None,Control,Refresh,Globals};explicit PartModulationTask(Kind k):kind_(k){}Kind kind()const{return kind_;}Stage stage()const{return stage_;}uint8_t part()const{return part_;}uint8_t input()const{return input_;}uint16_t word()const{return word_;}uint8_t gate()const{return gate_;}uint8_t value()const{return kind_==Kind::Square?uint8_t(word_>>8):input_;}uint16_t field()const{return kind_==Kind::First?6:kind_==Kind::Second?8:7;}
 Child child()const{switch(stage_){case Stage::AwaitControl:return Child::Control;case Stage::AwaitRefresh:return Child::Refresh;case Stage::AwaitGlobals:return Child::Globals;default:return Child::None;}}bool resumeChild(uint8_t part=0){switch(stage_){case Stage::AwaitControl:part_=part;stage_=(kind_==Kind::First||kind_==Kind::Second)?Stage::StoreByte:Stage::CaptureInput;return true;case Stage::AwaitRefresh:stage_=kind_==Kind::Cutoff?Stage::Finish:Stage::DispatchGlobals;return true;case Stage::AwaitGlobals:stage_=Stage::Finish;return true;default:return false;}}
 template<class StoreClock>unsigned nextClocks(StoreClock&&store)const{switch(stage_){case Stage::DispatchControl:case Stage::DispatchRefresh:case Stage::DispatchGlobals:return 20;case Stage::SetSentinel:return 6;case Stage::StoreCutoff:case Stage::ReadGate:return 15;case Stage::StoreByte:return 12+store();case Stage::SquareInput:return 15;case Stage::Finish:return 17;case Stage::AwaitControl:case Stage::AwaitRefresh:case Stage::AwaitGlobals:case Stage::Complete:return 0;default:return 3;}}
 template<class Reader,class Writer,class StoreClock>unsigned advanceBefore(unsigned available,Reader&&read,Writer&&write,StoreClock&&store){unsigned used=0;while(auto cost=nextClocks(store)){if(cost>available-used)break;switch(stage_){case Stage::DispatchControl:stage_=Stage::AwaitControl;break;case Stage::CaptureInput:input_=uint8_t(read(Read::Input));word_=input_;stage_=kind_==Kind::Cutoff?Stage::ClearHigh:Stage::SquareInput;break;case Stage::ClearHigh:stage_=Stage::CompareSentinel;break;case Stage::CompareSentinel:stage_=Stage::AdmitSentinel;break;case Stage::AdmitSentinel:stage_=input_==255?Stage::SetSentinel:Stage::ScaleCutoff;break;case Stage::SetSentinel:word_=256;stage_=Stage::ScaleCutoff;break;case Stage::ScaleCutoff:word_=uint16_t(word_<<1);stage_=Stage::StoreCutoff;break;case Stage::StoreCutoff:write(true,word_);stage_=Stage::DispatchRefresh;break;case Stage::StoreByte:if(kind_!=Kind::Square)input_=uint8_t(read(Read::Input));write(false,value());stage_=Stage::ReadGate;break;case Stage::SquareInput:word_=unsigned(input_)*input_;stage_=Stage::ScaleSquare;break;case Stage::ScaleSquare:word_=uint16_t(word_<<1);stage_=Stage::StoreByte;break;case Stage::ReadGate:gate_=uint8_t(read(Read::Gate));stage_=Stage::AdmitGate;break;case Stage::AdmitGate:stage_=gate_?Stage::Finish:Stage::DispatchRefresh;break;case Stage::DispatchRefresh:stage_=Stage::AwaitRefresh;break;case Stage::DispatchGlobals:stage_=Stage::AwaitGlobals;break;case Stage::Finish:stage_=Stage::Complete;break;default:break;}used+=cost;}return used;}
private:Kind kind_;Stage stage_=Stage::DispatchControl;uint8_t part_=0,input_=0,gate_=0;uint16_t word_=0;
};}
